import matter from 'gray-matter';

export interface FrontmatterData {
  title?: string;
  date?: string;
  tags?: string[];
  [key: string]: unknown;
}

export interface ParsedMarkdown {
  data: FrontmatterData;
  content: string;
}

const FRONTMATTER_BLOCK = /^---\r?\n([\s\S]*?)\r?\n---\r?\n?/;

/**
 * Parses a single `key: value` line from a YAML-ish frontmatter block.
 * Supports quoted strings, bracketed arrays (`[a, b, c]`) and bare scalars.
 */
function parseValue(raw: string): unknown {
  const value = raw.trim();

  if (
    (value.startsWith('"') && value.endsWith('"')) ||
    (value.startsWith("'") && value.endsWith("'"))
  ) {
    return value.slice(1, -1);
  }

  if (value.startsWith('[') && value.endsWith(']')) {
    const inner = value.slice(1, -1).trim();
    if (inner === '') return [];
    return inner.split(',').map((item) => stripQuotes(item.trim()));
  }

  return value;
}

function stripQuotes(value: string): string {
  if (
    (value.startsWith('"') && value.endsWith('"')) ||
    (value.startsWith("'") && value.endsWith("'"))
  ) {
    return value.slice(1, -1);
  }
  return value;
}

/**
 * gray-matter only parses JSON frontmatter out of the box, so YAML blocks
 * (the format used throughout this project) must be split out manually
 * with a simple `key: value` line parser and merged into gray-matter's
 * output afterwards.
 */
export function parseYamlFrontmatter(block: string): FrontmatterData {
  const data: FrontmatterData = {};
  const lines = block.split(/\r?\n/);

  for (const line of lines) {
    if (!line.trim() || line.trim().startsWith('#')) continue;

    const separatorIndex = line.indexOf(':');
    if (separatorIndex === -1) continue;

    const key = line.slice(0, separatorIndex).trim();
    const rawValue = line.slice(separatorIndex + 1).trim();
    if (!key) continue;

    if (key === 'tags') {
      if (rawValue.startsWith('[')) {
        data.tags = parseValue(rawValue) as string[];
      } else if (rawValue === '') {
        data.tags = [];
      } else {
        data.tags = rawValue.split(',').map((tag) => stripQuotes(tag.trim())).filter(Boolean);
      }
    } else {
      data[key] = parseValue(rawValue);
    }
  }

  return data;
}

export function parseMarkdownFile(raw: string): ParsedMarkdown {
  let content = raw;
  let grayMatterData: Record<string, unknown> = {};

  try {
    const parsed = matter(raw);
    content = parsed.content;
    grayMatterData = parsed.data || {};
  } catch {
    // gray-matter cannot parse YAML frontmatter out of the box; fall back
    // to manually stripping the block below.
  }

  const match = FRONTMATTER_BLOCK.exec(raw);
  let yamlData: FrontmatterData = {};
  if (match) {
    yamlData = parseYamlFrontmatter(match[1]);
    content = raw.slice(match[0].length);
  }

  const data: FrontmatterData = { ...grayMatterData, ...yamlData };

  return { data, content: content.trim() };
}

import { marked } from 'marked';

marked.setOptions({ gfm: true, breaks: false });

export function renderMarkdown(content: string): string {
  return marked.parse(content, { async: false }) as string;
}

export interface Page {
  slug: string;
  title: string;
  date: string | null;
  tags: string[];
  html: string;
  sourcePath: string;
  outputPath: string;
}

function escapeHtml(value: string): string {
  return value
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;')
    .replace(/'/g, '&#39;');
}

export function renderPageHtml(page: Page): string {
  const tagsHtml = page.tags.length
    ? `<ul class="tags">${page.tags.map((tag) => `<li>${escapeHtml(tag)}</li>`).join('')}</ul>`
    : '';
  const dateHtml = page.date ? `<p class="date">${escapeHtml(page.date)}</p>` : '';

  return `<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<title>${escapeHtml(page.title)}</title>
</head>
<body>
<a href="index.html">&larr; Back to index</a>
<h1>${escapeHtml(page.title)}</h1>
${dateHtml}
${tagsHtml}
<article>
${page.html}
</article>
</body>
</html>
`;
}

export function renderIndexHtml(pages: Page[]): string {
  const items = pages
    .map((page) => {
      const dateHtml = page.date ? ` <span class="date">${escapeHtml(page.date)}</span>` : '';
      return `<li><a href="${escapeHtml(page.outputPath)}">${escapeHtml(page.title)}</a>${dateHtml}</li>`;
    })
    .join('\n');

  return `<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<title>Index</title>
</head>
<body>
<h1>Index</h1>
<ul class="pages">
${items}
</ul>
</body>
</html>
`;
}

import * as fs from 'fs';
import * as path from 'path';
import { parseMarkdownFile } from './frontmatter';
import { renderMarkdown } from './markdown';
import { Page, renderIndexHtml, renderPageHtml } from './page';

export interface BuildOptions {
  contentDir: string;
  outputDir: string;
}

export interface BuildResult {
  pages: Page[];
  outputDir: string;
}

function findMarkdownFiles(dir: string): string[] {
  if (!fs.existsSync(dir)) {
    throw new Error(`Content directory not found: ${dir}`);
  }

  const results: string[] = [];
  const entries = fs.readdirSync(dir, { withFileTypes: true });

  for (const entry of entries) {
    const fullPath = path.join(dir, entry.name);
    if (entry.isDirectory()) {
      results.push(...findMarkdownFiles(fullPath));
    } else if (entry.isFile() && /\.md$/i.test(entry.name)) {
      results.push(fullPath);
    }
  }

  return results.sort();
}

function slugFromPath(contentDir: string, filePath: string): string {
  const relative = path.relative(contentDir, filePath);
  const withoutExt = relative.replace(/\.md$/i, '');
  return withoutExt.split(path.sep).join('/');
}

function titleFromSlug(slug: string): string {
  const base = slug.split('/').pop() || slug;
  return base
    .replace(/[-_]+/g, ' ')
    .replace(/\b\w/g, (char) => char.toUpperCase());
}

export function buildPage(contentDir: string, filePath: string): Page {
  const raw = fs.readFileSync(filePath, 'utf-8');
  const { data, content } = parseMarkdownFile(raw);
  const slug = slugFromPath(contentDir, filePath);
  const html = renderMarkdown(content);

  const title = typeof data.title === 'string' && data.title.trim() ? data.title : titleFromSlug(slug);
  const date = typeof data.date === 'string' && data.date.trim() ? data.date : null;
  const tags = Array.isArray(data.tags) ? data.tags.map(String) : [];

  return {
    slug,
    title,
    date,
    tags,
    html,
    sourcePath: filePath,
    outputPath: `${slug}.html`,
  };
}

export function buildSite(options: BuildOptions): BuildResult {
  const contentDir = path.resolve(options.contentDir);
  const outputDir = path.resolve(options.outputDir);

  const files = findMarkdownFiles(contentDir);
  const pages = files.map((file) => buildPage(contentDir, file));

  fs.mkdirSync(outputDir, { recursive: true });

  for (const page of pages) {
    const destPath = path.join(outputDir, page.outputPath);
    fs.mkdirSync(path.dirname(destPath), { recursive: true });
    fs.writeFileSync(destPath, renderPageHtml(page), 'utf-8');
  }

  const indexPath = path.join(outputDir, 'index.html');
  fs.writeFileSync(indexPath, renderIndexHtml(pages), 'utf-8');

  return { pages, outputDir };
}

#!/usr/bin/env node
import { Command } from 'commander';
import { buildSite } from './site';

export function run(argv: string[]): void {
  const program = new Command();

  program.name('ssg').description('A static site generator CLI');

  program
    .command('build')
    .description('Generate the site from Markdown content')
    .option('--content <dir>', 'content directory', './content')
    .option('--output <dir>', 'output directory', './dist')
    .action((opts: { content: string; output: string }) => {
      const result = buildSite({ contentDir: opts.content, outputDir: opts.output });
      // eslint-disable-next-line no-console
      console.log(`Built ${result.pages.length} page(s) into ${result.outputDir}`);
    });

  program.parse(argv);
}

if (require.main === module) {
  run(process.argv);
}

import { parseMarkdownFile, parseYamlFrontmatter } from './frontmatter';

describe('parseYamlFrontmatter', () => {
  it('parses simple key: value pairs', () => {
    const data = parseYamlFrontmatter('title: Hello World\ndate: 2026-01-15');
    expect(data.title).toBe('Hello World');
    expect(data.date).toBe('2026-01-15');
  });

  it('parses bracketed tag arrays', () => {
    const data = parseYamlFrontmatter('tags: [intro, welcome]');
    expect(data.tags).toEqual(['intro', 'welcome']);
  });

  it('parses comma separated tags without brackets', () => {
    const data = parseYamlFrontmatter('tags: intro, welcome');
    expect(data.tags).toEqual(['intro', 'welcome']);
  });

  it('parses a single bare tag into a one element array', () => {
    const data = parseYamlFrontmatter('tags: info');
    expect(data.tags).toEqual(['info']);
  });

  it('strips surrounding quotes from values', () => {
    const data = parseYamlFrontmatter('title: "Quoted Title"');
    expect(data.title).toBe('Quoted Title');
  });

  it('ignores blank lines and comments', () => {
    const data = parseYamlFrontmatter('# comment\n\ntitle: Hello\n');
    expect(data.title).toBe('Hello');
    expect(Object.keys(data)).toEqual(['title']);
  });
});

describe('parseMarkdownFile', () => {
  it('extracts YAML frontmatter and body content', () => {
    const raw = `---
title: Hello World
date: 2026-01-15
tags: [intro, welcome]
---

# Hello World

Body text.
`;
    const { data, content } = parseMarkdownFile(raw);
    expect(data.title).toBe('Hello World');
    expect(data.date).toBe('2026-01-15');
    expect(data.tags).toEqual(['intro', 'welcome']);
    expect(content).toContain('# Hello World');
    expect(content).toContain('Body text.');
    expect(content).not.toContain('---');
  });

  it('handles files with no frontmatter', () => {
    const raw = '# Just a heading\n\nSome text.';
    const { data, content } = parseMarkdownFile(raw);
    expect(data).toEqual({});
    expect(content).toBe(raw);
  });

  it('handles a single bare tag value', () => {
    const raw = `---
title: About
tags: info
---
Content here.
`;
    const { data } = parseMarkdownFile(raw);
    expect(data.tags).toEqual(['info']);
  });
});

import { renderMarkdown } from './markdown';

describe('renderMarkdown', () => {
  it('renders headings', () => {
    expect(renderMarkdown('# Hello')).toContain('<h1>Hello</h1>');
  });

  it('renders bold and italic text', () => {
    const html = renderMarkdown('This is **bold** and *italic*.');
    expect(html).toContain('<strong>bold</strong>');
    expect(html).toContain('<em>italic</em>');
  });

  it('renders unordered lists', () => {
    const html = renderMarkdown('- one\n- two\n- three');
    expect(html).toContain('<ul>');
    expect(html).toContain('<li>one</li>');
    expect(html).toContain('<li>two</li>');
  });

  it('renders links', () => {
    const html = renderMarkdown('[example](https://example.com)');
    expect(html).toContain('<a href="https://example.com">example</a>');
  });

  it('renders code blocks', () => {
    const html = renderMarkdown('```\nconst x = 1;\n```');
    expect(html).toContain('<pre>');
    expect(html).toContain('const x = 1;');
  });
});

import * as fs from 'fs';
import * as os from 'os';
import * as path from 'path';
import { buildSite } from './site';

function makeTmpDir(prefix: string): string {
  return fs.mkdtempSync(path.join(os.tmpdir(), prefix));
}

describe('buildSite', () => {
  let contentDir: string;
  let outputDir: string;

  beforeEach(() => {
    contentDir = makeTmpDir('ssg-content-');
    outputDir = makeTmpDir('ssg-output-');
  });

  afterEach(() => {
    fs.rmSync(contentDir, { recursive: true, force: true });
    fs.rmSync(outputDir, { recursive: true, force: true });
  });

  it('generates an HTML file per markdown page', () => {
    fs.writeFileSync(
      path.join(contentDir, 'hello.md'),
      '---\ntitle: Hello\ndate: 2026-01-01\ntags: [a, b]\n---\n\n# Hi there\n'
    );
    fs.writeFileSync(
      path.join(contentDir, 'second.md'),
      '---\ntitle: Second Page\n---\n\nSome content.\n'
    );

    const result = buildSite({ contentDir, outputDir });

    expect(result.pages).toHaveLength(2);
    expect(fs.existsSync(path.join(outputDir, 'hello.html'))).toBe(true);
    expect(fs.existsSync(path.join(outputDir, 'second.html'))).toBe(true);

    const helloHtml = fs.readFileSync(path.join(outputDir, 'hello.html'), 'utf-8');
    expect(helloHtml).toContain('<h1>Hello</h1>');
    expect(helloHtml).toContain('Hi there');
    expect(helloHtml).toContain('a');
    expect(helloHtml).toContain('b');
  });

  it('generates an index.html listing all pages', () => {
    fs.writeFileSync(path.join(contentDir, 'one.md'), '---\ntitle: One\n---\nBody one.');
    fs.writeFileSync(path.join(contentDir, 'two.md'), '---\ntitle: Two\n---\nBody two.');

    buildSite({ contentDir, outputDir });

    const indexPath = path.join(outputDir, 'index.html');
    expect(fs.existsSync(indexPath)).toBe(true);

    const indexHtml = fs.readFileSync(indexPath, 'utf-8');
    expect(indexHtml).toContain('One');
    expect(indexHtml).toContain('Two');
    expect(indexHtml).toContain('href="one.html"');
    expect(indexHtml).toContain('href="two.html"');
  });

  it('falls back to a title derived from the filename when frontmatter has none', () => {
    fs.writeFileSync(path.join(contentDir, 'my-cool-post.md'), 'No frontmatter here.');

    const result = buildSite({ contentDir, outputDir });

    expect(result.pages[0].title).toBe('My Cool Post');
  });

  it('supports nested content directories', () => {
    fs.mkdirSync(path.join(contentDir, 'posts'));
    fs.writeFileSync(
      path.join(contentDir, 'posts', 'nested.md'),
      '---\ntitle: Nested Post\n---\nNested body.'
    );

    const result = buildSite({ contentDir, outputDir });

    expect(result.pages[0].outputPath).toBe('posts/nested.html');
    expect(fs.existsSync(path.join(outputDir, 'posts', 'nested.html'))).toBe(true);
  });

  it('throws a clear error when the content directory does not exist', () => {
    const missingDir = path.join(contentDir, 'does-not-exist');
    expect(() => buildSite({ contentDir: missingDir, outputDir })).toThrow(/not found/i);
  });
});

import * as fs from 'fs';
import * as os from 'os';
import * as path from 'path';
import { run } from './cli';

function makeTmpDir(prefix: string): string {
  return fs.mkdtempSync(path.join(os.tmpdir(), prefix));
}

describe('ssg build CLI', () => {
  let contentDir: string;
  let outputDir: string;
  let logSpy: jest.SpyInstance;

  beforeEach(() => {
    contentDir = makeTmpDir('ssg-cli-content-');
    outputDir = makeTmpDir('ssg-cli-output-');
    logSpy = jest.spyOn(console, 'log').mockImplementation(() => {});
  });

  afterEach(() => {
    fs.rmSync(contentDir, { recursive: true, force: true });
    fs.rmSync(outputDir, { recursive: true, force: true });
    logSpy.mockRestore();
  });

  it('builds a site using the --content and --output options', () => {
    fs.writeFileSync(
      path.join(contentDir, 'page.md'),
      '---\ntitle: CLI Page\n---\n\nHello from the CLI.'
    );

    run(['node', 'ssg', 'build', '--content', contentDir, '--output', outputDir]);

    expect(fs.existsSync(path.join(outputDir, 'index.html'))).toBe(true);
    expect(fs.existsSync(path.join(outputDir, 'page.html'))).toBe(true);
    expect(logSpy).toHaveBeenCalledWith(expect.stringContaining('Built 1 page(s)'));
  });
});
